import pandas as pd

def clean(df):
    df = df.copy()
    # 1. Drop exact duplicate rows (2 duplicates identified)
    df = df.drop_duplicates().reset_index(drop=True)

    # 2. Normalize Category label variants (e.g. 'office supplies' -> 'Office Supplies')
    df['Category'] = df['Category'].astype(str).str.strip().str.title()

    # 3. Fix Region typos; leave missing regions as NaN (not needed for this question)
    region_fix = {'Suoth': 'South', 'Eats': 'East'}
    df['Region'] = df['Region'].replace(region_fix)

    # 4. Parse dates: ISO first, then fall back to common alternative formats
    def parse_date(v):
        if pd.isna(v):
            return pd.NaT
        s = str(v).strip()
        for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y', '%Y/%m/%d',
                    '%m-%d-%Y', '%d-%m-%Y', '%b %d, %Y', '%d %b %Y',
                    '%B %d, %Y', '%d %B %Y'):
            try:
                return pd.to_datetime(s, format=fmt)
            except (ValueError, TypeError):
                continue
        return pd.to_datetime(s, errors='coerce')

    df['Date'] = df['Date'].apply(parse_date)

    # 5. Enforce Revenue = Quantity * Price (fix any cross-column inconsistencies)
    df['Revenue'] = df['Quantity'] * df['Price']

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Date'])
    d['month'] = d['Date'].dt.strftime('%Y-%m')
    d = d.dropna(subset=['month'])
    grouped = d.groupby('month')['Revenue'].sum()
    return {k: float(v) for k, v in grouped.items()}
